901	    /// Visit a SQL literal (like [visit_literal]), but return AnyValue instead of Expr.
902	    fn visit_any_value(
903	        &self,
904	        value: &SQLValue,
905	        op: Option<&SQLUnaryOperator>,
906	    ) -> PolarsResult<AnyValue<'_>> {
907	        Ok(match value {
908	            SQLValue::Boolean(b) => AnyValue::Boolean(*b),
909	            SQLValue::DollarQuotedString(s) => AnyValue::StringOwned(s.clone().value.into()),
910	            #[cfg(feature = "binary_encoding")]
911	            SQLValue::HexStringLiteral(x) => {
912	                if x.len() % 2 != 0 {
913	                    polars_bail!(SQLSyntax: "hex string literal must have an even number of digits; found '{}'", x)
914	                };
915	                AnyValue::BinaryOwned(
916	                    hex::decode(x.clone()).map_err(
917	                        |_| polars_err!(SQLSyntax: "invalid hex string literal: '{}'", x),
918	                    )?,
919	                )
920	            },
921	            SQLValue::Null => AnyValue::Null,
922	            SQLValue::Number(s, _) => {
923	                let negate = match op {
924	                    Some(SQLUnaryOperator::Minus) => true,
925	                    // no op should be taken as plus.
926	                    Some(SQLUnaryOperator::Plus) | None => false,
927	                    Some(op) => {
928	                        polars_bail!(SQLInterface: "unary op {:?} not supported for numeric SQL value", op)
929	                    },
930	                };
931	                // Check for existence of decimal separator dot
932	                if s.contains('.') {
933	                    s.parse::<f64>()
934	                        .map(|n: f64| AnyValue::Float64(if negate { -n } else { n }))
935	                        .map_err(|_| ())
936	                } else {
937	                    s.parse::<i64>()
938	                        .map(|n: i64| AnyValue::Int64(if negate { -n } else { n }))
939	                        .map_err(|_| ())
940	                }
941	                .map_err(|_| polars_err!(SQLInterface: "cannot parse literal: {:?}", s))?
942	            },
943	            SQLValue::SingleQuotedByteStringLiteral(b) => {
944	                // note: for PostgreSQL this represents a BIT literal (eg: b'10101') not BYTE
945	                let bytes_literal = bitstring_to_bytes_literal(b)?;
946	                match bytes_literal {
947	                    Expr::Literal(lv) if lv.extract_binary().is_some() => {
948	                        AnyValue::BinaryOwned(lv.extract_binary().unwrap().to_vec())
949	                    },
950	                    _ => {
951	                        polars_bail!(SQLInterface: "failed to parse bitstring literal: {:?}", b)
952	                    },
953	                }
954	            },
955	            SQLValue::SingleQuotedString(s) => AnyValue::StringOwned(s.as_str().into()),
956	            other => polars_bail!(SQLInterface: "value {:?} is not currently supported", other),
957	        })
958	    }
